    adc  r5, r11
    adc  r6, r12
    adc  r7, r13
__mods32_out:
    mov  r24, r4        ; remainder -> output registers
    mov  r25, r5
    mov  r22, r6
    mov  r23, r7
    pop  r13
    pop  r12
    pop  r11
    pop  r10
    pop  r9
    pop  r8
    pop  r7
    pop  r6
    pop  r5
    pop  r4
    ret


